INSERT INTO mt_promotion_log_read_state (
    shop_id, last_read_record_id, last_read_at, create_time, update_time
) VALUES (
    #{shopId}, #{lastReadRecordId}, #{lastReadAt}, #{lastReadAt}, #{lastReadAt}
)
ON DUPLICATE KEY UPDATE
    last_read_record_id = GREATEST(COALESCE(last_read_record_id, 0), COALESCE(VALUES(last_read_record_id), 0)),
    last_read_at = VALUES(last_read_at),
    update_time = VALUES(update_time)
